/* Renal and Urinary question set (v4.1). Original items written for this app from
   RENAL_AND_URINARY_SYSTEM_FINAL_MASTER.pdf (PDF pages cited per item) and the Ch. 41 urinary drug supplement.
   Not recalled or proprietary HESI items. Each item names its lesson in the Renal linear path. */
(function () {
const RM = "RENAL_AND_URINARY_SYSTEM_FINAL_MASTER.pdf", UD = "Urinary_Drugs_UTI_Supplement.md (Ch. 41)";
const RU = "Renal/Urinary", FE = "Fluids & Electrolytes";
const PA = "Physiological Adaptation", RR = "Reduction of Risk Potential", PT = "Pharmacological Therapies", SF = "Safety and Infection Prevention and Control", BC = "Basic Care and Comfort", CC = "Coordinated Care", HP = "Health Promotion and Maintenance";
const Q = o => Object.assign({ src: RM, why: {} }, o);
const NGN = o => Q(Object.assign({ ngn: true }, o));
window.SRC_QS = (window.SRC_QS || []).concat([
/* ---------- Calculations ---------- */
NGN({id:"RNM01",lesson:"rn-assess",subj:RU,topic:"Weight-based urine output",cn:RR,fmt:"num",diff:"I",ask:"Calculate",comp:"cue",cj:"Analyze cues",
 stem:"An 80-kg adult has 180 mL of urine over the past 6 hours. Calculate the urine output in mL/kg/hr. Round to two decimal places.",key:0.38,unit:"mL/kg/hr",tol:0.01,
 rat:"180 mL ÷ 6 hr = 30 mL/hr; 30 ÷ 80 kg = 0.375 → 0.38 mL/kg/hr. This is below 0.5 mL/kg/hr for 6 hours, which meets a published AKI urine-output criterion — even though '30 mL/hr' passes the old bedside shortcut. Confirm the measurement, check for obstruction, assess perfusion, and report.",
 aid:"Divide twice: by hours, then by kilograms.",principle:"Use weight-based output, not a fixed hourly number.",takeaway:"30 mL/hr is under 0.5 mL/kg/hr for anyone over 60 kg.",pg:"PDF pp. 6, 19, 42"}),
NGN({id:"RNM02",lesson:"rn-stones-bph",subj:RU,topic:"Continuous bladder irrigation: true urine output",cn:BC,fmt:"num",diff:"I",ask:"Calculate",comp:"cue",cj:"Analyze cues",
 stem:"A client is on continuous bladder irrigation after a TURP. During an 8-hour shift, 2,900 mL of irrigant infused and the drainage bag collected 3,600 mL. What is the client's true urine output for the shift?",key:700,unit:"mL",tol:0,
 rat:"True urine output = total drainage − irrigant infused for the same period: 3,600 − 2,900 = 700 mL. Recording 3,600 mL would hide low output. Irrigant in and drainage out are documented separately.",
 aid:"Out minus in = urine.",principle:"Subtract what you put in before calling it urine.",takeaway:"Irrigation drainage is mostly irrigant.",pg:"PDF pp. 15, 38, 42"}),
NGN({id:"RNM03",lesson:"rn-assess",subj:RU,topic:"Minimum hourly output for body weight",cn:RR,fmt:"num",diff:"F",ask:"Calculate",comp:"cue",cj:"Recognize cues",
 stem:"What hourly urine output equals 0.5 mL/kg/hr for a 92-kg adult?",key:46,unit:"mL/hr",tol:0,
 rat:"0.5 mL/kg/hr × 92 kg = 46 mL/hr. For this client, sustained output below 46 mL/hr for 6 hours meets an AKI criterion; a fixed 30 mL/hr alert would miss it.",
 aid:"Half the weight in kilograms = the hourly floor in mL.",principle:"Scale output expectations to weight.",takeaway:"Half the kilograms = the hourly minimum.",pg:"PDF p. 6"}),
/* ---------- Dialysis ---------- */
Q({id:"RNM04",lesson:"rn-dialysis",subj:RU,topic:"Cloudy peritoneal dialysis effluent",cn:SF,fmt:"mc",diff:"I",ask:"Intervene",comp:"priority",
 stem:"A client on peritoneal dialysis reports that the fluid drained this morning is cloudy and that the abdomen has started to hurt. What should the nurse do first?",
 opts:["Contact the PD team urgently, check vital signs for sepsis, and keep the drained fluid for ordered testing","Discard the cloudy bag and start the next exchange on schedule","Have the client take acetaminophen and call back if the pain lasts 2 days","Explain that cloudy fluid is expected after a long overnight dwell"],key:0,
 rat:"Cloudy effluent or new abdominal pain warrants immediate PD team contact and evaluation for peritonitis. The effluent is preserved for cell count, differential, and culture, and systemic instability is reported immediately.",
 why:{"1":"Discarding the effluent loses the sample needed for diagnosis and delays care.","2":"Waiting delays treatment of possible peritonitis.","3":"Cloudy effluent is not an expected finding."},
 aid:"Cloudy = contaminated until proven otherwise.",principle:"Infection signs in a dialysis client are escalated, not observed.",takeaway:"Cloudy PD fluid: call, assess, save the bag.",pg:"PDF pp. 36, 40"}),
Q({id:"RNM05",lesson:"rn-dialysis",subj:RU,topic:"Dizziness after hemodialysis",cn:SF,fmt:"mc",diff:"F",ask:"Intervene",comp:"intervention",
 stem:"Right after hemodialysis, a client says, 'I feel dizzy,' and starts to stand to walk to the bathroom. What should the nurse do first?",
 opts:["Help the client back to a safe position and check BP, perfusion, symptoms, and the access site","Walk the client to the bathroom and recheck BP afterward","Give the scheduled antihypertensive now that dialysis is finished","Encourage the client to drink 1 liter of water"],key:0,
 rat:"Dizziness right after treatment suggests hypotension from fluid removal. Assist safely, check BP, perfusion, symptoms, bleeding, and recent fluid removal, report persistent or severe hypotension, and escalate chest pain, altered mentation, or significant bleeding.",
 why:{"1":"Walking a hypotensive client risks a fall.","2":"An antihypertensive would worsen low BP.","3":"Large fluid intake conflicts with fluid limits and doesn't assess the problem."},
 aid:"Dizzy after dialysis = check the pressure before the steps.",principle:"Safety and assessment before activity.",takeaway:"Post-HD dizziness: sit, check BP, report.",pg:"PDF pp. 35, 42"}),
Q({id:"RNM06",lesson:"rn-dialysis",subj:RU,topic:"Dialysis disequilibrium",cn:PA,fmt:"mc",diff:"I",ask:"Interpret",comp:"cue",
 stem:"During a client's second-ever hemodialysis treatment, the client develops a new headache, vomits, and becomes confused. What do these findings most likely indicate?",
 opts:["Possible dialysis disequilibrium or another emergency that needs escalation","Expected tiredness after dialysis","Fistula maturation","Low phosphate from the binder"],key:0,
 rat:"New headache, vomiting, or neurologic changes during or after early treatment can indicate dialysis disequilibrium or another emergency and need escalation.",
 why:{"1":"Neurologic change is not expected fatigue.","2":"Fistula maturation does not cause these symptoms.","3":"Binders are not linked to these acute neurologic signs."},
 aid:"Early dialysis + head, gut, and brain symptoms = disequilibrium until proven otherwise.",principle:"New neurologic change is always escalated.",takeaway:"Early HD + headache, vomiting, confusion → escalate.",pg:"PDF p. 35"}),
Q({id:"RNM07",lesson:"rn-dialysis",subj:RU,topic:"AV fistula care",cn:SF,fmt:"sata",diff:"F",ask:"Intervene",comp:"intervention",
 stem:"Which actions are appropriate for a client with a left-arm AV fistula used for hemodialysis? Select all that apply.",
 opts:["Palpate for a thrill and listen for a bruit as trained","Check the left hand for coldness, pallor, pain, or numbness","Take blood pressures on the right arm","Report a newly absent thrill to the dialysis team promptly","Apply a snug elastic sleeve over the fistula for protection","Start the IV in the left arm because the vein is large"],key:[0,1,2,3],
 rat:"Inspect the site, assess thrill and bruit if trained, check the distal limb for coldness, pallor, pain, or numbness, protect the access arm from routine BP cuffs, venipuncture, and compression, and report a newly absent thrill or bruit promptly.",
 why:{"4":"Compression can damage or clot the access.","5":"Venipuncture on the access arm is avoided."},
 aid:"Feel the thrill, hear the bruit, protect the arm.",principle:"Protect the lifeline.",takeaway:"Nothing tight and no needles on the access arm.",pg:"PDF p. 35"}),
/* ---------- Potassium ---------- */
Q({id:"RNM08",lesson:"rn-fe",subj:FE,topic:"Hyperkalemia emergency care",cn:PA,fmt:"sata",diff:"A",ask:"Intervene",comp:"intervention",
 stem:"A client with kidney failure has a potassium of 6.9 mEq/L with peaked T waves. Which actions and expectations are correct? Select all that apply.",
 opts:["Place the client on continuous cardiac monitoring","Anticipate IV calcium to stabilize the heart as ordered","Monitor blood glucose after ordered insulin with dextrose","Expect the IV calcium to bring the potassium level down","Recheck the serum potassium after treatment","Offer orange juice to keep the client hydrated"],key:[0,1,2,4],
 rat:"Potassium ≥ 6.5 mEq/L or ECG changes require emergency escalation. Calcium stabilizes cardiac membranes but does not lower potassium; insulin/dextrose and selected beta agonists shift potassium into cells; dialysis, diuretics, or binders remove it. Insulin creates delayed hypoglycemia risk, especially in kidney failure, so rhythm, serial potassium, and glucose are monitored.",
 why:{"3":"Calcium protects the heart; it does not lower potassium.","5":"Orange juice is high in potassium."},
 aid:"Shield (calcium), shift (insulin + dextrose), remove (dialysis, binders).",principle:"Know what each treatment does — and doesn't do.",takeaway:"Calcium is the heart's raincoat; potassium is still high.",pg:"PDF pp. 27, 33, 40"}),
NGN({id:"RNM09",lesson:"rn-fe",subj:FE,topic:"Hyperkalemia vs hypokalemia findings",cn:PA,fmt:"matrix",diff:"I",ask:"Interpret",comp:"cue",cj:"Recognize cues",
 stem:"For each finding, indicate whether it is more consistent with hyperkalemia or hypokalemia.",
 rows:["Peaked T waves","Prominent U waves","Flattened T waves with ileus","Bradycardia with a widened QRS","Client taking spironolactone with CKD","Client with vomiting taking furosemide"],cols:["Hyperkalemia","Hypokalemia"],key:[0,1,1,0,0,1],
 rat:"Hyperkalemia: weakness, paresthesias, bradycardia, ECG changes such as peaked T waves and widened QRS; causes include low renal excretion and potassium-sparing drugs. Hypokalemia: weakness, ileus, flattened T waves, prominent U waves, dysrhythmias; causes include GI losses and loop or thiazide diuretics.",
 aid:"High K⁺ = tall, peaked T. Low K⁺ = flat T and a U wave.",principle:"Match the ECG and the cause.",takeaway:"Spironolactone + CKD → high K⁺; furosemide + vomiting → low K⁺.",pg:"PDF pp. 27, 30, 40"}),
NGN({id:"RNM10",lesson:"rn-fe",subj:FE,topic:"Hyperkalemia treatment roles",cn:PT,fmt:"cloze",diff:"I",ask:"Interpret",comp:"med",cj:"Generate solutions",
 stem:"Complete the statement about emergency hyperkalemia treatment.",
 text:"IV calcium {0} the cardiac membrane.\nInsulin with dextrose {1} potassium into the cells.\nDialysis or a potassium binder {2} potassium from the body.\nAfter insulin, the nurse watches especially for {3}.",
 blanks:[{opts:["stabilizes","lowers potassium in","removes potassium from"],key:0},{opts:["shifts","removes","excretes"],key:0},{opts:["removes","shifts","stabilizes"],key:0},{opts:["delayed hypoglycemia","hypernatremia","hypercalcemia"],key:0}],
 rat:"Calcium stabilizes cardiac membranes (it does not lower potassium). Insulin and beta agonists shift potassium temporarily. Dialysis, selected diuretics, or binders remove it. Insulin creates delayed hypoglycemia risk, particularly in kidney failure.",
 aid:"Shield, shift, remove — then check sugar.",principle:"Each drug has one job.",takeaway:"Insulin for K⁺ → glucose checks afterward.",pg:"PDF pp. 27, 33"}),
Q({id:"RNM11",lesson:"rn-fe",subj:FE,topic:"Refractory hypokalemia",cn:PA,fmt:"mc",diff:"A",ask:"Interpret",comp:"analysis",
 stem:"A client's potassium stays low despite two days of ordered replacement. Which lab result should the nurse check?",
 opts:["Magnesium","Hemoglobin A1c","Lipase","Ammonia"],key:0,
 rat:"Low magnesium can hinder potassium repletion and promote dysrhythmia. The master pairs hypokalemia with checking magnesium and renal function.",
 why:{"1":"A1c reflects long-term glucose control.","2":"Lipase reflects the pancreas.","3":"Ammonia reflects liver function."},
 aid:"Mag is the key that lets K⁺ stay in.",principle:"When a replacement 'won't stick,' look for the partner electrolyte.",takeaway:"Stubborn low K⁺ → check Mg.",pg:"PDF pp. 7, 27–28"}),
/* ---------- Glomerular ---------- */
NGN({id:"RNM12",lesson:"rn-glom",subj:RU,topic:"Nephritic vs nephrotic syndrome",cn:PA,fmt:"matrix",diff:"I",ask:"Interpret",comp:"cue",cj:"Analyze cues",
 stem:"For each finding, indicate whether it is more typical of nephritic syndrome or nephrotic syndrome.",
 rows:["Tea- or cola-colored urine","Foamy urine","RBC casts on microscopy","Markedly low serum albumin","Hypertension as a leading feature","Elevated lipids","Raised risk of venous thrombosis"],cols:["Nephritic","Nephrotic"],key:[0,1,0,1,0,1,1],
 rat:"Nephritic (glomerulonephritis): tea- or cola-colored urine, RBC casts or dysmorphic RBCs, hypertension, oliguria. Nephrotic: heavy proteinuria with foamy urine, low serum albumin, edema, hyperlipidemia, and complications such as venous thromboembolism and infection.",
 aid:"nephrITic = Inflammation (blood, BP). nephrOtic = prOtein (foam, low albumin, clots).",principle:"Group the cues before naming the condition.",takeaway:"Blood + BP vs protein + edema.",pg:"PDF pp. 20–22, 41"}),
Q({id:"RNM13",lesson:"rn-glom",subj:RU,topic:"Nephrotic syndrome: thrombosis",cn:RR,fmt:"highlight",diff:"A",ask:"Interpret",comp:"cue",ngn:true,cj:"Recognize cues",
 stem:"A client with nephrotic syndrome is being monitored. Highlight each finding in the nurse's note that needs prompt follow-up.",
 segs:[{t:"1000 Nurse's note: ",s:false},{t:"Foamy urine in the collection container.",s:true},{t:" ",s:false},{t:"Periorbital puffiness, same as yesterday.",s:true},{t:" ",s:false},{t:"New swelling of the left calf only; right calf unchanged.",s:true},{t:" ",s:false},{t:"Says she suddenly feels short of breath.",s:true},{t:" ",s:false},{t:"Temperature 101.3°F (38.5°C).",s:true},{t:" ",s:false},{t:"Weight up 0.2 kg from yesterday.",s:true}],key:[5,7,9],
 rat:"Nephrotic syndrome carries risk of venous thromboembolism and infection. New unilateral leg swelling needs evaluation for thrombosis; sudden dyspnea raises concern for pulmonary embolism; fever suggests infection. Foamy urine and stable periorbital edema are expected features, and a 0.2-kg change is minor.",
 why:{"1":"Foamy urine is an expected sign of proteinuria.","3":"Unchanged periorbital edema is part of the known picture.","11":"A 0.2-kg change is minor."},
 aid:"Nephrotic dangers hide: clots and infection.",principle:"Separate the expected disease picture from new danger cues.",takeaway:"New one-sided leg swelling or sudden dyspnea → escalate.",pg:"PDF pp. 22, 42"}),
Q({id:"RNM14",lesson:"rn-glom",subj:RU,topic:"ADPKD: sudden severe headache",cn:PA,fmt:"mc",diff:"I",ask:"Prioritize",comp:"priority",
 stem:"A client with autosomal dominant polycystic kidney disease (ADPKD) says, 'This is the worst headache of my life — it came on all at once.' What should the nurse do?",
 opts:["Activate urgent evaluation immediately","Give acetaminophen and dim the lights","Recheck in 1 hour after the client rests","Encourage fluids for possible dehydration"],key:0,
 rat:"A sudden severe headache in ADPKD can signal a neurologic emergency (intracranial aneurysm risk in selected patients). Activate urgent evaluation.",
 why:{"1":"Comfort measures alone delay emergency care.","2":"Waiting delays care.","3":"Dehydration does not explain a sudden 'worst' headache."},
 aid:"PKD + thunderclap headache = aneurysm until proven otherwise.",principle:"New sudden neurologic symptoms are emergencies.",takeaway:"ADPKD + worst headache → urgent evaluation.",pg:"PDF pp. 22–23"}),
/* ---------- AKI / CKD ---------- */
NGN({id:"RNM15",lesson:"rn-aki",subj:RU,topic:"KDIGO AKI criteria",cn:RR,fmt:"cloze",diff:"I",ask:"Interpret",comp:"cue",cj:"Recognize cues",
 stem:"Complete the published AKI criteria.",
 text:"AKI is present with a creatinine rise of {0} within 48 hours,\nor a rise to {1} times baseline within the prior 7 days,\nor urine output below {2} for 6 hours.",
 blanks:[{opts:["≥ 0.3 mg/dL","≥ 1.0 mg/dL","≥ 0.1 mg/dL"],key:0},{opts:["1.5","1.1","4"],key:0},{opts:["0.5 mL/kg/hr","30 mL/hr","1 mL/kg/hr"],key:0}],
 rat:"KDIGO criteria: creatinine increase ≥ 0.3 mg/dL within 48 hours, ≥ 1.5 times baseline within the prior 7 days, or urine output < 0.5 mL/kg/hr for 6 hours. A fixed 30 mL/hr alert is a bedside convention, not the criterion.",
 aid:"'0.3 – 1.5 – 0.5'.",principle:"Use defined criteria, not a vague sense of 'low'.",takeaway:"0.3 in 48 h · 1.5× in 7 days · < 0.5 mL/kg/hr × 6 h.",pg:"PDF pp. 6, 18"}),
NGN({id:"RNM16",lesson:"rn-aki",subj:RU,topic:"Fluid overload in AKI",cn:PA,fmt:"bowtie",diff:"A",ask:"Interpret",comp:"analysis",cj:"Prioritize hypotheses",
 exhibit:"<table><tr><th>Time</th><th>BP</th><th>HR</th><th>RR</th><th>SpO₂</th><th>Other</th></tr><tr><td>0700</td><td>148/88</td><td>92</td><td>20</td><td>95% RA</td><td>Output 15 mL/hr; weight up 2 kg since admission</td></tr><tr><td>1100</td><td>164/96</td><td>108</td><td>28</td><td>88% RA</td><td>Crackles both bases; must sit up to breathe; JVD</td></tr></table>",
 stem:"A client with AKI is trended below. Complete the bow-tie: the condition the client is most likely developing, 2 actions to take now, and 2 parameters to monitor.",
 cond:{opts:["Pulmonary edema from fluid overload","Hypovolemic shock","Pneumonia","Dialysis disequilibrium"],key:0},
 act:{opts:["Sit the client upright and apply oxygen per protocol","Escalate to the provider or rapid response now","Give a 500-mL normal saline bolus","Lay the client flat to rest","Encourage oral fluids"],key:[0,1]},
 par:{opts:["Oxygen saturation and work of breathing","Daily weight and intake and output","Bowel sounds","Pupil size","Capillary glucose only"],key:[0,1]},
 rat:"Rising weight, low output, hypertension, crackles, orthopnea, JVD, and falling SpO₂ signal fluid overload with pulmonary edema. Sit the client upright if tolerated, assess ABCs, give protocol oxygen, and escalate; anticipate diuresis or dialysis. Monitor oxygenation, breathing, weights, and true fluid balance. Never give a reflex fluid bolus without assessing overload.",
 why:{"Hypovolemic shock":"BP and weight are rising, not falling.","Pneumonia":"No fever or sputum; the picture follows fluid gain.","Dialysis disequilibrium":"The client is not on dialysis.","Give a 500-mL normal saline bolus":"Adds fluid to an overloaded client.","Lay the client flat to rest":"Worsens breathing in pulmonary edema.","Encourage oral fluids":"Adds fluid.","Bowel sounds":"Doesn't track this problem.","Pupil size":"Doesn't track this problem.","Capillary glucose only":"Doesn't track this problem."},
 aid:"Weight up + output down + crackles = the lungs are filling.",principle:"Breathing threats outrank the creatinine trend.",takeaway:"AKI + crackles + low SpO₂: upright, oxygen, escalate.",pg:"PDF pp. 19, 27, 40"}),
Q({id:"RNM17",lesson:"rn-aki",subj:RU,topic:"Rhabdomyolysis cues",cn:PA,fmt:"mc",diff:"A",ask:"Interpret",comp:"cue",
 stem:"After a long crush injury, a client has dark urine. The dipstick is strongly positive for blood, but microscopy shows few RBCs. CK is markedly elevated. Which lab result is the priority to check?",
 opts:["Serum potassium","Serum amylase","Hemoglobin A1c","Urine specific gravity"],key:0,
 rat:"Rhabdomyolysis can cause dark urine, dipstick blood with few RBCs (myoglobin), marked CK elevation, and hyperkalemia. Prompt electrolyte and volume assessment is critical because high potassium can cause lethal dysrhythmias.",
 why:{"1":"Amylase isn't the threat here.","2":"A1c reflects long-term glucose.","3":"Specific gravity doesn't address the immediate danger."},
 aid:"Muscle breaks → K⁺ leaks out.",principle:"Find the lab that threatens the heart.",takeaway:"Rhabdo → check K⁺ first.",pg:"PDF pp. 8, 19"}),
NGN({id:"RNM18",lesson:"rn-ckd",subj:RU,topic:"CKD GFR categories",cn:RR,fmt:"cloze",diff:"F",ask:"Interpret",comp:"cue",cj:"Recognize cues",
 stem:"Complete the statements about CKD.",
 text:"CKD requires abnormalities present for at least {0}.\nCategory G3a is an eGFR of {1} mL/min/1.73 m².\nCategory G4 is {2}.\nCategory G5, the kidney failure category, is {3}.",
 blanks:[{opts:["3 months","3 weeks","1 year"],key:0},{opts:["45–59","30–44","60–89"],key:0},{opts:["15–29","30–44","< 15"],key:0},{opts:["< 15","15–29","< 30"],key:0}],
 rat:"CKD is abnormal kidney structure or function with health implications for at least 3 months. GFR categories: G1 ≥ 90, G2 60–89, G3a 45–59, G3b 30–44, G4 15–29, G5 < 15.",
 aid:"90 · 60 · 45 · 30 · 15.",principle:"Know the cut points.",takeaway:"G5 < 15, but dialysis start depends on the patient.",pg:"PDF pp. 19–20"}),
NGN({id:"RNM19",lesson:"rn-ckd",subj:RU,topic:"Uremic complications in ESKD",cn:PA,fmt:"highlight",diff:"A",ask:"Interpret",comp:"cue",cj:"Recognize cues",
 stem:"A client with ESKD on hemodialysis is assessed before treatment. Highlight each finding that needs prompt escalation.",
 segs:[{t:"0800: ",s:false},{t:"Mild generalized itching, unchanged for months.",s:true},{t:" ",s:false},{t:"Sharp chest pain that is worse lying flat and better leaning forward.",s:true},{t:" ",s:false},{t:"A scratchy rub heard over the heart.",s:true},{t:" ",s:false},{t:"Metallic taste in the mouth.",s:true},{t:" ",s:false},{t:"Newly confused about the day and place.",s:true},{t:" ",s:false},{t:"Gums bleeding and not stopping after brushing.",s:true}],key:[3,5,9,11],
 rat:"Uremic complications to escalate include positional chest pain or a friction rub (possible uremic pericarditis), confusion (possible encephalopathy), and unexpected bleeding. Chronic mild itching and a metallic taste are common uremic symptoms but not emergencies on their own.",
 why:{"1":"Long-standing mild pruritus is a common, chronic symptom.","7":"Metallic taste is a common uremic symptom, not an emergency by itself."},
 aid:"Uremia emergencies: heart (rub, positional pain), head (confusion), blood (bleeding).",principle:"Separate chronic symptoms from new threats.",takeaway:"Rub, positional chest pain, confusion, bleeding → escalate.",pg:"PDF pp. 24–25, 41"}),
Q({id:"RNM20",lesson:"rn-ckd",subj:RU,topic:"ESKD nutrition and medication teaching",cn:HP,fmt:"sata",diff:"I",ask:"Teach",comp:"teach",
 stem:"Which statements by a client with ESKD show understanding of the teaching? Select all that apply.",
 opts:["'I'll check salt substitutes, because many contain potassium.'","'I'll take my phosphate binder with my meal, as prescribed.'","'I'll learn which foods and drinks count toward my fluid limit.'","'I'll weigh myself daily if that's what my team prescribes.'","'If a food is low in sodium, it must be low in potassium too.'","'Ibuprofen is fine for my aches since it's over the counter.'"],key:[0,1,2,3],
 rat:"Teaching includes individualized sodium, fluid, potassium, phosphate, and protein plans; which foods and drinks count as fluid; checking potassium-containing salt substitutes and phosphate additives; pairing the binder with the prescribed meal; daily weights when prescribed; and consulting the team before OTC NSAIDs. A low-sodium choice can still contain substantial potassium.",
 why:{"4":"A low-sodium choice can still be high in potassium.","5":"OTC NSAIDs are avoided without the team's approval."},
 aid:"Binder with the bite; read labels for K⁺ and phosphate.",principle:"Evaluate each statement on its own.",takeaway:"Low sodium ≠ low potassium.",pg:"PDF pp. 20, 39"}),
/* ---------- UTI and bacteriuria ---------- */
NGN({id:"RNM21",lesson:"rn-uti",subj:RU,topic:"Cystitis, pyelonephritis, or asymptomatic bacteriuria",cn:PA,fmt:"matrix",diff:"A",ask:"Interpret",comp:"cue",cj:"Analyze cues",
 stem:"For each client, select the condition the findings best match.",
 rows:["Dysuria, frequency, urgency; afebrile","Fever, flank pain, CVA tenderness, vomiting","Positive urine culture; no urinary or systemic symptoms","Suprapubic discomfort and a nitrite-positive dipstick; afebrile","Chills, nausea, and WBC casts in the urine"],cols:["Cystitis","Pyelonephritis","Asymptomatic bacteriuria"],key:[0,1,2,0,1],
 rat:"Dysuria and frequency suggest lower-tract irritation (cystitis). Fever, flank pain, CVA tenderness, and vomiting point to pyelonephritis; WBC casts can occur with kidney infection. A positive culture without attributable symptoms commonly represents asymptomatic bacteriuria.",
 aid:"Lower = local. Upper = unwell. Culture + no symptoms = colonized.",principle:"Locate the infection by its symptoms.",takeaway:"A positive culture alone is not a UTI.",pg:"PDF pp. 8, 10–11, 37"}),
NGN({id:"RNM22",lesson:"rn-uti",subj:RU,topic:"Infected obstructing stone",cn:PA,fmt:"bowtie",diff:"A",ask:"Interpret",comp:"analysis",cj:"Take action",
 exhibit:"<table><tr><th>Time</th><th>T</th><th>BP</th><th>HR</th><th>Other</th></tr><tr><td>0900</td><td>99.0°F</td><td>132/80</td><td>94</td><td>Right flank pain 8/10; CT: 8-mm obstructing ureteral stone with hydronephrosis</td></tr><tr><td>1300</td><td>102.4°F</td><td>96/58</td><td>122</td><td>Chills; new restlessness; output 15 mL/hr</td></tr></table>",
 stem:"Complete the bow-tie for this client: the condition most likely developing, 2 actions to take, and 2 parameters to monitor.",
 cond:{opts:["Infected obstruction with possible sepsis","Uncomplicated renal colic","Acute cystitis","Prerenal AKI from dehydration only"],key:0},
 act:{opts:["Escalate immediately for urgent evaluation and decompression","Obtain ordered cultures and start ordered antibiotics without delay","Encourage 3 liters of oral fluid to flush the stone","Give the opioid and reassess in 2 hours","Strain the urine as the first priority"],key:[0,1]},
 par:{opts:["Blood pressure, heart rate, and temperature","Urine output and mental status","Bowel sounds","Stool color","Visual acuity"],key:[0,1]},
 rat:"Fever with a known obstructing stone is an emergency: infected obstruction needs urgent decompression plus antibiotics, and pain relief alone can mask deterioration. Cultures are obtained without delaying therapy. Monitor perfusion (BP, HR, temperature), urine output, and mental status. Fluids are not forced during suspected obstruction.",
 why:{"Uncomplicated renal colic":"Fever, hypotension, and tachycardia make this complicated.","Acute cystitis":"Flank pain with obstruction and systemic signs is not lower-tract infection.","Prerenal AKI from dehydration only":"The obstruction and fever explain the picture.","Encourage 3 liters of oral fluid to flush the stone":"Don't force fluids against an obstruction.","Give the opioid and reassess in 2 hours":"Pain relief alone can mask deterioration.","Strain the urine as the first priority":"Straining comes after the emergency is addressed.","Bowel sounds":"Doesn't track sepsis or obstruction.","Stool color":"Doesn't track this problem.","Visual acuity":"Doesn't track this problem."},
 aid:"Stone + fever = drain it and treat it.",principle:"Sepsis signs change the priority.",takeaway:"Fever + obstruction → escalate, cultures, antibiotics, decompression.",pg:"PDF pp. 11, 13–14, 40"}),
Q({id:"RNM23",lesson:"rn-uti",subj:RU,topic:"Nitrofurantoin for pyelonephritis",cn:PT,fmt:"mc",diff:"I",ask:"Clarify",comp:"med",
 stem:"A client with a temperature of 102°F, flank pain, and CVA tenderness has a new order for oral nitrofurantoin. What should the nurse do?",
 opts:["Clarify the order, because nitrofurantoin is not appropriate for routine kidney infection","Give it with food to reduce stomach upset","Give it and tell the client the urine may turn rust brown","Hold it until the urine culture results return, without notifying anyone"],key:0,
 rat:"The findings suggest pyelonephritis. Nitrofurantoin and single-dose oral fosfomycin are inappropriate for routine kidney infection; pyelonephritis needs culture-directed drugs with renal tissue penetration. The nurse clarifies the order.",
 why:{"1":"Correct administration teaching for the wrong drug and indication.","2":"Correct teaching, but the drug doesn't fit the infection site.","3":"Holding without notifying delays treatment."},
 aid:"NF = 'Not For' pyelonephritis.",principle:"Verify that the drug fits the site of infection.",takeaway:"Bladder-only drugs don't treat the kidney.",pg:"PDF pp. 11, 31; Ch. 41 nitrofurantoin"}),
Q({id:"RNM24",lesson:"rn-uti",subj:RU,topic:"Phenazopyridine teaching",cn:PT,fmt:"mc",diff:"F",ask:"Teach",comp:"teach",
 stem:"A client with cystitis says, 'This orange pill fixed my burning, so I'll just keep taking it for a week instead of the antibiotic.' What is the nurse's best response?",
 opts:["'It relieves pain but doesn't kill bacteria; it's usually used no more than 2 days along with the antibiotic.'","'That's fine as long as the burning stays away.'","'You can stop the antibiotic once your urine turns orange.'","'Take double the dose so it works like an antibiotic.'"],key:0,
 rat:"Phenazopyridine is a urinary analgesic with no antibacterial activity; under U.S. labeling it is generally used no more than two days with antibacterial therapy. Reddish-orange urine is expected; yellow skin or sclera is reported.",
 why:{"1":"Pain relief doesn't treat the infection.","2":"Orange urine is a drug effect, not a cure.","3":"Doubling raises toxicity risk and still doesn't treat infection."},
 aid:"Pyridium = Pain pill, not a Penicillin.",principle:"Symptom relief is not cure.",takeaway:"Phenazopyridine ≤ 2 days with the antibiotic.",pg:"PDF p. 32; Ch. 41 phenazopyridine"}),
Q({id:"RNM25",lesson:"rn-uti",subj:RU,topic:"Asymptomatic bacteriuria",cn:SF,fmt:"mc",diff:"I",ask:"Teach",comp:"teach",
 stem:"An 86-year-old nursing home resident is afebrile with stable vital signs, no urinary symptoms, and usual mental status. A routine urine culture grew bacteria. The daughter asks why antibiotics weren't started. What is the nurse's best response?",
 opts:["'Bacteria in the urine without symptoms usually isn't treated in adults who aren't pregnant; we'll keep watching for fever or new symptoms.'","'Every positive culture is treated right away in older adults.'","'We're waiting until she gets confused, then we'll treat.'","'Cranberry juice will cure it, so antibiotics aren't needed.'"],key:0,
 rat:"A positive culture without attributable urinary or systemic symptoms commonly represents asymptomatic bacteriuria; routine screening or treatment is generally inappropriate in nonpregnant adults, including many older or catheterized patients. Fever, hypotension, or other sepsis findings require urgent assessment.",
 why:{"1":"Treating asymptomatic bacteriuria is generally inappropriate.","2":"New confusion alone is assessed for other causes, not used as a trigger for automatic antibiotics.","3":"No source supports cranberry as a cure."},
 aid:"No symptoms = no treatment (unless pregnant or before some urologic procedures).",principle:"Treat the patient, not the culture.",takeaway:"Asymptomatic bacteriuria is watched, not treated.",pg:"PDF pp. 11, 37"}),
/* ---------- Retention / incontinence ---------- */
Q({id:"RNM26",lesson:"rn-retention",subj:RU,topic:"Retention with neurologic red flags",cn:PA,fmt:"mc",diff:"A",ask:"Prioritize",comp:"priority",
 stem:"A client has new inability to urinate, severe low back pain, numbness of the buttocks and inner thighs, and leg weakness. What should the nurse do?",
 opts:["Arrange emergency evaluation immediately","Give bethanechol as needed","Pour warm water over the perineum to stimulate voiding","Reassess in 2 hours after the client drinks fluids"],key:0,
 rat:"New retention with saddle numbness, weakness, or severe back pain needs emergency evaluation. Bethanechol is for selected nonobstructive retention, and voiding tricks or waiting would delay care.",
 why:{"1":"A drug for nonobstructive retention doesn't address a neurologic emergency.","2":"A voiding aid delays emergency care.","3":"Waiting delays emergency care."},
 aid:"Saddle numbness + retention = spinal emergency.",principle:"Neurologic red flags override routine measures.",takeaway:"Retention + saddle numbness → emergency.",pg:"PDF p. 12"}),
Q({id:"RNM27",lesson:"rn-retention",subj:RU,topic:"Overflow vs urge incontinence",cn:PA,fmt:"mc",diff:"I",ask:"Intervene",comp:"analysis",
 stem:"An 80-year-old man with BPH dribbles urine constantly and has suprapubic fullness. An order for oxybutynin was written for 'urge incontinence.' What should the nurse do first?",
 opts:["Perform a bladder scan for residual urine before giving the drug","Give the oxybutynin as ordered","Restrict his fluids to reduce leakage","Insert an indwelling catheter for the incontinence"],key:0,
 rat:"Dribbling can be overflow from retention. The master says to assess residual before treating apparent urge leakage when obstruction is plausible; antimuscarinics can cause retention, and indwelling catheters are avoided for routine incontinence.",
 why:{"1":"An antimuscarinic could worsen retention.","2":"Fluid restriction doesn't address possible retention.","3":"Indwelling catheters aren't used for routine incontinence."},
 aid:"Dribbling + fullness = scan first.",principle:"Assess before treating a label.",takeaway:"Overflow looks like urge — scan first.",pg:"PDF pp. 12–13, 32, 37"}),
Q({id:"RNM28",lesson:"rn-retention",subj:RU,topic:"Bethanechol safety",cn:PT,fmt:"mc",diff:"I",ask:"Clarify",comp:"med",
 stem:"Bethanechol is ordered for a postoperative client who cannot void. Which finding should make the nurse hold the dose and clarify the order?",
 opts:["A bladder scan and exam suggest a mechanical obstruction","The client had a cesarean birth yesterday","The bladder scan shows 450 mL","The client reports mild lower-abdominal fullness"],key:0,
 rat:"Bethanechol stimulates bladder contraction for selected nonobstructive retention; mechanical obstruction must be excluded first. Bradycardia, hypotension, and bronchospasm are also reviewed before giving it.",
 why:{"1":"Postpartum or postoperative nonobstructive retention is a listed use.","2":"Retained urine is the reason it's ordered.","3":"Fullness is expected with retention."},
 aid:"Squeezing against a blocked outlet helps no one.",principle:"Know the contraindication before the dose.",takeaway:"Bethanechol only after obstruction is ruled out.",pg:"PDF pp. 12, 32; Ch. 41 bethanechol"}),
/* ---------- Stones / BPH ---------- */
NGN({id:"RNM29",lesson:"rn-stones-bph",subj:RU,topic:"After TURP with bladder irrigation",cn:RR,fmt:"matrix",diff:"I",ask:"Interpret",comp:"cue",cj:"Recognize cues",
 stem:"A client has continuous bladder irrigation after a TURP. For each finding, indicate whether it is expected or requires follow-up.",
 rows:["Light pink drainage with irrigation running at the ordered rate","Outflow less than inflow with a distended, painful bladder","Bright red drainage with large clots","New confusion with a slowing heart rate in recovery","Shift drainage 3,200 mL with 2,700 mL irrigant infused"],cols:["Expected","Requires follow-up"],key:[0,1,1,1,0],
 rat:"Low outflow with distention suggests obstruction; heavy bleeding or large clots need escalation; new neurologic, respiratory, or hemodynamic changes may signal TUR syndrome. Light pink drainage is a common target with irrigation, and 3,200 − 2,700 = 500 mL true urine is an acceptable shift output.",
 aid:"Out < in + pain = blocked. Red + clots = bleeding. Confused = TUR syndrome?",principle:"Compare inflow and outflow every time.",takeaway:"True urine = drainage − irrigant.",pg:"PDF pp. 15, 38, 42"}),
Q({id:"RNM30",lesson:"rn-stones-bph",subj:RU,topic:"Calcium stone prevention teaching",cn:HP,fmt:"mc",diff:"I",ask:"Teach",comp:"teach",
 stem:"A client recovering from a calcium oxalate stone asks about diet. Which statement by the client shows understanding?",
 opts:["'I'll keep normal calcium in my diet unless my provider says otherwise, and cut back on salt.'","'I'll stop all dairy so my body has no calcium to form stones.'","'I'll add extra salt to make myself drink more water.'","'Diet doesn't matter once the stone has passed.'"],key:0,
 rat:"Normal dietary calcium is generally retained for calcium stone prevention unless advised otherwise; limit excess sodium and follow the stone-specific fluid and diet plan.",
 why:{"1":"Cutting dietary calcium is not the master's recommendation.","2":"High sodium intake is a stone risk factor.","3":"Prevention continues after the stone passes."},
 aid:"Keep the calcium, cut the salt.",principle:"Teach the evidence-based plan, not the myth.",takeaway:"Calcium stones: normal calcium, less sodium.",pg:"PDF pp. 13–14"}),
Q({id:"RNM31",lesson:"rn-stones-bph",subj:RU,topic:"Tamsulosin teaching",cn:PT,fmt:"mc",diff:"F",ask:"Teach",comp:"teach",
 stem:"A client starting tamsulosin for BPH asks what to watch for. Which instruction is most important?",
 opts:["'Get up slowly; the drug can make you dizzy when you stand, and tell your eye surgeon before cataract surgery.'","'Take it only when your stream is weak.'","'Expect your PSA test to be cut in half.'","'Stop it if you have to urinate at night.'"],key:0,
 rat:"Alpha-1 blockers relax prostatic and bladder-outlet smooth muscle; watch dizziness, falls, orthostasis, and ejaculation effects, and inform the ophthalmic team before cataract surgery. Changes in PSA interpretation apply to 5-alpha-reductase inhibitors, not tamsulosin.",
 why:{"1":"It's taken as prescribed, not as needed.","2":"PSA changes are a 5-ARI effect.","3":"Nocturia is a BPH symptom, not a reason to stop."},
 aid:"Flomax = Flow max, but Floor (falls) risk.",principle:"Teach the safety risk first.",takeaway:"Alpha blockers: rise slowly; tell the eye surgeon.",pg:"PDF pp. 15, 32"}),
/* ---------- Catheters / specimens ---------- */
Q({id:"RNM32",lesson:"rn-catheter",subj:RU,topic:"CAUTI prevention",cn:SF,fmt:"sata",diff:"I",ask:"Intervene",comp:"intervention",
 stem:"Which actions help prevent catheter-associated urinary tract infection? Select all that apply.",
 opts:["Keep the drainage bag below bladder level and off the floor","Maintain a closed drainage system","Review the need for the catheter daily and remove it promptly per order or protocol","Empty the bag into a clean container without touching the outlet","Change the catheter every 3 days on a routine schedule","Irrigate the catheter routinely to prevent blockage","Collect culture specimens from the drainage bag"],key:[0,1,2,3],
 rat:"Maintain a closed system, unobstructed flow, and a bag below bladder level and off the floor; empty into a clean separate container without touching the outlet; review the need daily and remove promptly. Routine fixed-interval changes, routine antimicrobial prophylaxis, and routine irrigation are generally unnecessary. Cultures come from the disinfected sampling port, never the bag.",
 why:{"4":"Routine fixed-interval changes are generally unnecessary.","5":"Routine irrigation is generally unnecessary and opens the system.","6":"Bag urine is not used for culture."},
 aid:"Below, closed, flowing, off the floor, out ASAP.",principle:"Each break in the system is a doorway for bacteria.",takeaway:"No routine changes or irrigation; culture from the port.",pg:"PDF pp. 8, 37"}),
Q({id:"RNM33",lesson:"rn-catheter",subj:RU,topic:"Low output with an indwelling catheter",cn:RR,fmt:"mc",diff:"I",ask:"Intervene",comp:"priority",
 stem:"A client's Foley catheter drained 5 mL/hr for 2 hours after draining 60 mL/hr earlier. The bag is on the floor and the tubing has a loop hanging below the bed. What should the nurse do first?",
 opts:["Inspect the tubing and bag position, straighten the loop, and check for bladder distention","Give a 500-mL fluid bolus","Irrigate the catheter routinely","Document and recheck at the end of the shift"],key:0,
 rat:"When output drops, inspect the patient and the system, measure I&O, check for bladder distention, and assess catheter obstruction versus low renal production. If the bladder is empty, consider shock, AKI, or upper obstruction. Fluids are not given without a volume assessment, and routine irrigation is unnecessary.",
 why:{"1":"Volume is assessed before fluid; the problem may be mechanical.","2":"Routine irrigation is unnecessary and needs an order.","3":"Waiting delays care."},
 aid:"Check the plumbing before blaming the kidney.",principle:"Assess the equipment and the bladder first.",takeaway:"Low catheter output: tubing, bag, bladder scan.",pg:"PDF pp. 37, 40–41"}),
NGN({id:"RNM34",lesson:"rn-assess",subj:RU,topic:"24-hour urine collection",cn:RR,fmt:"order",diff:"F",ask:"Sequence",comp:"intervention",cj:"Take action",
 stem:"Put the steps of a 24-hour urine collection in order.",
 opts:["Have the client void at the start time and discard that urine","Collect all urine for the next 24 hours, stored as the lab directs","At the end time, have the client void and add it to the collection","Label the container and send it promptly; report any missed void"],key:[0,1,2,3],
 rat:"For timed urine, discard the first void at the start, collect all subsequent urine through the final timed void, follow the laboratory's storage directions, and report any missed collection.",
 aid:"Toss the first, keep the rest, include the last.",principle:"Start with an empty bladder; end with an empty bladder.",takeaway:"Discard the first void; keep the last.",pg:"PDF p. 8"}),
Q({id:"RNM35",lesson:"rn-assess",subj:RU,topic:"After renal biopsy",cn:RR,fmt:"sata",diff:"I",ask:"Interpret",comp:"cue",
 stem:"Four hours after a percutaneous renal biopsy, which findings should the nurse escalate? Select all that apply.",
 opts:["BP has fallen from 132/80 to 96/58","HR has risen from 80 to 118","Gross blood in the urine","Hemoglobin dropped from 11.8 to 9.6 g/dL","Clear yellow urine at 60 mL/hr","BP 130/78, unchanged from baseline"],key:[0,1,2,3],
 rat:"After renal biopsy, monitor vitals, urine, puncture site, and new flank pain; escalate hypotension, tachycardia, gross hematuria, or falling hemoglobin.",
 why:{"4":"Clear urine at a good rate is reassuring.","5":"Stable BP is reassuring."},
 aid:"Biopsy = a needle in a blood-rich organ: watch for bleeding.",principle:"Trend vitals and hemoglobin after invasive procedures.",takeaway:"Post-biopsy: low BP, high HR, red urine, falling Hgb → escalate.",pg:"PDF p. 9"}),
NGN({id:"RNM36",lesson:"rn-dialysis",subj:RU,topic:"Peritoneal dialysis exchange steps",cn:SF,fmt:"order",diff:"I",ask:"Sequence",comp:"intervention",cj:"Take action",
 stem:"Put the steps of a peritoneal dialysis exchange in order.",
 opts:["Verify the prescribed dialysate, concentration, volume, and dwell","Check the bag for leaks, clarity, and expiry; warm only with approved equipment","Perform hand hygiene and connect using the taught aseptic technique","Drain the effluent and inspect it, then infuse the new dialysate","Record inflow, outflow, appearance, and net ultrafiltration"],key:[0,1,2,3,4],
 rat:"Use the prescribed dialysate, concentration, volume, and dwell; check bag integrity, solution clarity, and expiry; warm with approved equipment only; perform hand hygiene and connection technique as taught; record inflow, outflow, appearance, and net ultrafiltration (outflow minus inflow).",
 aid:"Verify → inspect → clean hands → drain/fill → document.",principle:"Safety checks come before the connection.",takeaway:"Never warm dialysate with unapproved methods.",pg:"PDF p. 35"}),
/* ---------- Medications ---------- */
Q({id:"RNM37",lesson:"rn-meds",subj:RU,topic:"SGLT2 inhibitor teaching",cn:PT,fmt:"mc",diff:"A",ask:"Evaluate",comp:"teach",
 stem:"Which statement by a client starting empagliflozin for CKD shows correct understanding?",
 opts:["'If I'm sick and can't eat, I'll follow my hold plan and report vomiting even if my sugar isn't very high.'","'Ketoacidosis can only happen when my sugar is over 300.'","'Genital itching is expected, so I won't mention it.'","'I can keep taking it the morning of my surgery no matter what.'"],key:0,
 rat:"SGLT2 inhibitors can cause ketoacidosis with glucose below typical DKA levels; monitor volume, genital infection, and ketoacidosis symptoms, and follow the agent-specific hold plan for surgery, fasting, or critical illness.",
 why:{"1":"Ketoacidosis can occur with near-normal glucose.","2":"Genital infection is monitored and reported.","3":"There is an agent-specific hold plan around surgery."},
 aid:"SGLT2: Sick? Stop per plan. Sugar can lie.",principle:"Teach what makes the drug dangerous.",takeaway:"Euglycemic ketoacidosis is possible.",pg:"PDF p. 31"}),
Q({id:"RNM38",lesson:"rn-meds",subj:RU,topic:"ACE inhibitor creatinine rise",cn:PT,fmt:"mc",diff:"A",ask:"Clarify",comp:"med",
 stem:"Two weeks after starting lisinopril, a client's creatinine rose from 1.2 to 1.7 mg/dL and potassium is 5.6 mEq/L. What should the nurse do before the next dose?",
 opts:["Hold the dose per policy and report the creatinine and potassium changes","Give the dose; a rise in creatinine is always expected","Encourage a potassium salt substitute to reduce sodium","Suggest ibuprofen for the dry cough"],key:0,
 rat:"Monitor BP, creatinine, and potassium after starting or titrating ACE inhibitors or ARBs; a creatinine rise of 30% or more after initiation prompts evaluation (here about 42%), and ACE inhibitors raise potassium. Salt substitutes add potassium, and NSAIDs harm the kidney.",
 why:{"1":"Some rise can occur, but ≥ 30% with high K⁺ needs evaluation.","2":"Adds potassium.","3":"NSAIDs are avoided and the cough is reported."},
 aid:"New 'pril' + creatinine up ≥ 30% or K⁺ up → call.",principle:"Do the math on the trend.",takeaway:"(1.7 − 1.2) ÷ 1.2 ≈ 42% → report.",pg:"PDF pp. 30–31"}),
NGN({id:"RNM39",lesson:"rn-meds",subj:RU,topic:"Diuretic classes and hazards",cn:PT,fmt:"matrix",diff:"A",ask:"Interpret",comp:"med",cj:"Analyze cues",
 stem:"Match each diuretic with the hazard the renal master emphasizes for it.",
 rows:["Furosemide","Spironolactone","Hydrochlorothiazide","Acetazolamide","Mannitol"],cols:["Low K⁺ and Mg; possible ototoxicity","Hyperkalemia is the major hazard","Can raise calcium; hyperuricemia","Metabolic acidosis and stones","Early volume expansion; pulmonary edema risk"],key:[0,1,2,3,4],
 rat:"Loops (furosemide): volume depletion, low K/Mg/Na, hypotension, possible ototoxicity. Potassium-sparing (spironolactone): hyperkalemia. Thiazides: hyponatremia, low K/Mg, hyperuricemia, glucose effects, can raise calcium. Acetazolamide: metabolic acidosis, low K⁺, stones. Mannitol: may first expand intravascular volume, then diurese; watch for pulmonary edema.",
 aid:"Loop loses; spiro saves K⁺; thiazide keeps Ca²⁺; aceta-acid; mannitol floods first.",principle:"Link each drug to its signature risk.",takeaway:"Each diuretic has a different danger.",pg:"PDF p. 30"}),
/* ---------- Transplant ---------- */
Q({id:"RNM40",lesson:"rn-dialysis",subj:RU,topic:"Possible kidney transplant rejection",cn:PA,fmt:"mc",diff:"I",ask:"Prioritize",comp:"priority",
 stem:"Three months after a kidney transplant, a client reports less urine, a temperature of 100.6°F, and tenderness over the graft. BP is higher than usual. What should the nurse do?",
 opts:["Notify the transplant team promptly","Reassure the client that this is normal adjustment","Tell the client to skip tacrolimus until seen","Suggest ibuprofen for the tenderness"],key:0,
 rat:"After transplant, declining urine, rising creatinine, fever, graft pain, or hypertension can reflect rejection, obstruction, drug effects, vascular complications, or infection; notify the transplant team promptly. Immunosuppressants are time-sensitive, and OTC drugs are checked with the team.",
 why:{"1":"These are warning signs, not normal adjustment.","2":"Stopping immunosuppression risks rejection.","3":"NSAIDs can harm the graft and aren't taken without the team."},
 aid:"Graft pain + less urine + fever = call the transplant team.",principle:"Possible rejection is time-sensitive.",takeaway:"Rejection can be silent — act on any sign.",pg:"PDF pp. 33, 36"}),
/* ---------- Added for lesson coverage ---------- */
Q({id:"RNM41",lesson:"rn-ap",subj:RU,topic:"Aldosterone and potassium",cn:PT,fmt:"mc",diff:"I",ask:"Interpret",comp:"analysis",
 stem:"A client with CKD takes spironolactone. Which explanation of the nephron best accounts for the client's rising potassium?",
 opts:["Blocking aldosterone in the late distal nephron reduces potassium secretion","Blocking NKCC2 in the thick ascending loop increases potassium loss","Blocking the proximal tubule increases glucose in the urine","ADH increases potassium excretion in the collecting duct"],key:0,
 rat:"Aldosterone promotes sodium reabsorption and potassium secretion in the late distal nephron and collecting duct. Spironolactone blocks aldosterone effects, so less potassium is secreted; hyperkalemia is the major renal hazard, especially with reduced kidney function.",
 why:{"1":"That describes loop diuretics, which lower potassium.","2":"That describes SGLT2 inhibitors.","3":"ADH governs water, not potassium excretion."},
 aid:"Aldosterone: Absorb sodium, Away goes K⁺. Block it and K⁺ stays.",principle:"Link the drug to the nephron segment.",takeaway:"Aldosterone blockers keep K⁺.",pg:"PDF pp. 4–5, 30"}),
Q({id:"RNM42",lesson:"rn-ap",subj:RU,topic:"Kidney hormones and CKD anemia",cn:PA,fmt:"mc",diff:"F",ask:"Interpret",comp:"analysis",
 stem:"A client with advanced CKD has a low hemoglobin. Which kidney function most directly explains this?",
 opts:["Reduced erythropoietin production","Reduced renin release","Increased ADH release","Increased bicarbonate reabsorption"],key:0,
 rat:"Reduced erythropoietin contributes to CKD anemia; iron deficiency, bleeding, and inflammation can coexist, so CBC and iron indices (ferritin, TSAT) are reviewed.",
 why:{"1":"Renin affects BP and sodium, not red cell production.","2":"ADH affects water balance.","3":"Kidney failure tends to lower bicarbonate, and it doesn't cause anemia."},
 aid:"'A WET BED': E = Erythropoietin.",principle:"Map each CKD complication to the lost kidney job.",takeaway:"Low EPO → CKD anemia.",pg:"PDF pp. 5, 7, 25"}),
Q({id:"RNM43",lesson:"rn-cancer",subj:RU,topic:"Painless hematuria",cn:HP,fmt:"mc",diff:"F",ask:"Teach",comp:"teach",
 stem:"A 66-year-old who has smoked for 40 years saw blood in the urine twice this week. 'It doesn't hurt, so it's probably nothing.' What is the nurse's best response?",
 opts:["'Visible blood in the urine needs evaluation even when it's painless — please keep the appointment for testing.'","'If it doesn't hurt, it's probably just a minor infection.'","'Drink more water and see if it clears in a month.'","'It's likely from your blood pressure pills.'"],key:0,
 rat:"Bladder cancer often presents with painless visible hematuria, and tobacco exposure increases risk. Persistent or visible hematuria merits evaluation even if painless or associated with anticoagulants; cystoscopy and imaging are guided by risk.",
 why:{"1":"Painless doesn't mean harmless.","2":"Waiting delays evaluation.","3":"Assumes a cause without evaluation."},
 aid:"Painless + visible blood + smoker = evaluate.",principle:"Don't reassure away a red flag.",takeaway:"Painless hematuria still needs a workup.",pg:"PDF pp. 15–16"}),
NGN({id:"RNM44",lesson:"rn-cancer",subj:RU,topic:"Ileal conduit stoma assessment",cn:RR,fmt:"matrix",diff:"I",ask:"Interpret",comp:"cue",cj:"Recognize cues",
 stem:"A client has an ileal conduit after cystectomy. For each finding, indicate whether it is expected or requires follow-up.",
 rows:["Small amount of mucus in the urine","Moist, pink-red stoma","Dusky, dark stoma","No urine output from the stoma for 3 hours","Red, broken skin around the stoma","Urine draining continuously into the pouch"],cols:["Expected","Requires follow-up"],key:[0,0,1,1,1,0],
 rat:"An ileal conduit drains continuously; small amounts of mucus occur because bowel tissue still makes mucus. A viable stoma is usually moist and pink/red. Report dusky, black, or very pale tissue, absent output or a sudden drop, fever, heavy bleeding, or skin breakdown.",
 aid:"Pink and moist with a little mucus = okay. Dark, dry output, or broken skin = call.",principle:"Know the normal stoma before judging the abnormal.",takeaway:"Mucus is normal in an ileal conduit.",pg:"PDF p. 38"}),
Q({id:"RNM45",lesson:"rn-catheter",subj:RU,topic:"Urine culture from an indwelling catheter",cn:SF,fmt:"mc",diff:"F",ask:"Intervene",comp:"intervention",
 stem:"A urine culture is ordered for a client with an indwelling catheter. How should the nurse obtain the specimen?",
 opts:["Disinfect the sampling port and withdraw fresh urine with aseptic technique","Pour urine from the drainage bag into the specimen cup","Disconnect the catheter from the tubing and let urine drip into the cup","Remove the catheter and send the tip"],key:0,
 rat:"For an indwelling catheter, obtain fresh urine from the disinfected sampling port with aseptic technique under facility policy. Avoid drainage-bag samples, keep the system closed, label the method, and send promptly.",
 why:{"1":"Bag urine is stagnant and contaminated.","2":"Disconnecting breaks the closed system.","3":"Catheter tips are not the ordered specimen."},
 aid:"Port, not pour.",principle:"Keep the system closed and the sample fresh.",takeaway:"Culture from the sampling port.",pg:"PDF pp. 8, 37"}),
Q({id:"RNM46",lesson:"rn-meds",subj:RU,topic:"Tacrolimus teaching after transplant",cn:PT,fmt:"sata",diff:"I",ask:"Teach",comp:"teach",
 stem:"Which instructions should the nurse reinforce with a client taking tacrolimus after a kidney transplant? Select all that apply.",
 opts:["Take each dose at the times prescribed","Follow the instructions for when to have trough blood levels drawn","Check with the transplant team before adding any OTC or herbal product","Report fever or other signs of infection","Stop the drug once your creatinine is normal","Get any live vaccine offered at the pharmacy"],key:[0,1,2,3],
 rat:"Immunosuppressant dosing is time-sensitive; tacrolimus can cause kidney injury and interacts with many drugs, so trough timing and adherence are verified and the transplant team is consulted before OTC or herbal products. Watch infection, glucose, and BP. Transplant recipients generally avoid live vaccines unless their transplant clinicians recommend otherwise.",
 why:{"4":"Stopping risks rejection; the drug is lifelong unless the team changes it.","5":"Live vaccines are generally avoided after transplant unless the team recommends them."},
 aid:"On time, on schedule, ask first, report fever.",principle:"Protect the graft and the immune-suppressed client.",takeaway:"Never stop anti-rejection drugs on your own.",pg:"PDF pp. 33, 36"}),
Q({id:"RNM47",lesson:"rn-meds",subj:RU,topic:"Finasteride handling",cn:PT,fmt:"mc",diff:"F",ask:"Teach",comp:"teach",
 stem:"A client starting finasteride for BPH lives with his pregnant partner. Which instruction is most important?",
 opts:["'Your partner should not handle crushed or broken tablets.'","'Take it only when your urine stream is weak.'","'It will shrink the prostate within 2 days.'","'Your PSA results won't be affected.'"],key:0,
 rat:"5-alpha-reductase inhibitors reduce dihydrotestosterone and shrink the prostate over months. Review pregnancy exposure precautions for damaged tablets and altered PSA interpretation.",
 why:{"1":"It's taken daily as prescribed.","2":"Effects take months.","3":"Finasteride changes PSA interpretation."},
 aid:"FINish slowly; pregnant hands off broken pills.",principle:"Teach the safety precaution first.",takeaway:"Pregnant people avoid damaged finasteride tablets.",pg:"PDF pp. 15, 32"})
]);
})();
